// --- Helper Functions ---

// Fetch file name from Google Drive public page via AllOrigins proxy
async function fetchFileNameFromDrive(driveId) {
  const targetUrl = `https://drive.google.com/file/d/${driveId}/view`;
  
  const proxies = [
    url => `https://corsproxy.io/?${encodeURIComponent(url)}`,
    url => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
    url => `https://thingproxy.freeboard.io/fetch/${url}`
  ];
  
  for (let i = 0; i < proxies.length; i++) {
    try {
      const proxyUrl = proxies[i](targetUrl);
      console.log(`Đang thử đồng bộ bằng proxy ${i + 1}/${proxies.length}...`);
      
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6000); // 6 seconds timeout per proxy
      
      const response = await fetch(proxyUrl, { signal: controller.signal });
      clearTimeout(timeoutId);
      
      if (!response.ok) throw new Error(`HTTP error ${response.status}`);
      
      const html = await response.text();
      if (!html) throw new Error('Empty HTML response');
      
      // Check if it's a Cloudflare error page or proxy error message
      if (html.includes('522: Connection timed out') || 
          html.includes('520: Web server') || 
          html.includes('Server-side requests are not allowed') ||
          html.includes('Rate limit exceeded')) {
        throw new Error('Proxy error or timeout');
      }
      
      let title = '';
      
      // 1. og:title
      const ogMatch = html.match(/<meta\s+property=["']og:title["']\s+content=["'](.*?)["']/i) || 
                      html.match(/<meta\s+content=["'](.*?)["']\s+property=["']og:title["']/i);
      if (ogMatch && ogMatch[1]) {
        title = ogMatch[1];
      }
      
      // 2. <title> tag
      if (!title) {
        const titleMatch = html.match(/<title>(.*?)<\/title>/i);
        if (titleMatch && titleMatch[1]) {
          title = titleMatch[1];
        }
      }
      
      if (title) {
        title = title.replace(/\s*-\s*Google\s*Drive/gi, '')
                     .replace(/\s*-\s*Google\s*trình\s*xem.*/gi, '')
                     .trim();
                     
        if (title && 
            !title.includes('Google Drive - Virus scan warning') && 
            !title.includes('Sign-in') && 
            !title.includes('Đăng nhập') &&
            !title.toLowerCase().includes('google drive')) {
          const txt = document.createElement('textarea');
          txt.innerHTML = title;
          const cleanedTitle = txt.value.trim();
          console.log(`Thành công lấy tên bằng proxy ${i + 1}: ${cleanedTitle}`);
          return cleanedTitle;
        }
      }
    } catch (err) {
      console.warn(`Proxy ${i + 1} thất bại:`, err.message);
    }
  }
  return null;
}

// Update file name in fileTreeData database and save
function updateFileName(driveId, newName) {
  let updated = false;
  fileTreeData.forEach(category => {
    category.subjects.forEach(subject => {
      subject.folders.forEach(folder => {
        folder.files.forEach(file => {
          if (file.driveId === driveId) {
            file.name = newName;
            updated = true;
          }
        });
      });
    });
  });
  if (updated) {
    saveData();
    updateFolderPanelFileNames();
  }
  return updated;
}

// Refresh the folder details panel file names if active
function updateFolderPanelFileNames() {
  if (activeFolder && elFolderPanel.classList.contains('active')) {
    selectFolder(activeFolder, false);
  }
}

// Trigger manual sync
async function syncActiveFileName() {
  if (!activeFile) return;
  const driveId = activeFile.driveId;
  const btnSyncName = document.getElementById('btn-sync-name');
  if (!btnSyncName) return;
  const originalHtml = btnSyncName.innerHTML;
  
  btnSyncName.disabled = true;
  btnSyncName.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span class="btn-text">Đang đồng bộ...</span>';
  
  showToast("Đang kết nối tới Google Drive...");
  const newName = await fetchFileNameFromDrive(driveId);
  
  if (newName) {
    const updated = updateFileName(driveId, newName);
    if (updated) {
      activeFile.name = newName;
      elActiveFileTitle.textContent = newName;
      showToast("Đồng bộ tên file thành công!");
    } else {
      showToast("Lỗi khi cập nhật tên file vào cơ sở dữ liệu!", "error");
    }
  } else {
    showToast("Không lấy được tên từ Drive. Hãy kiểm tra quyền chia sẻ công khai của file.", "error");
  }
  
  btnSyncName.disabled = false;
  btnSyncName.innerHTML = originalHtml;
}

// Trigger background automatic sync
async function autoSyncFileName(driveId) {
  const newName = await fetchFileNameFromDrive(driveId);
  if (newName && activeFile && activeFile.driveId === driveId) {
    const updated = updateFileName(driveId, newName);
    if (updated) {
      activeFile.name = newName;
      if (elActiveFileTitle && elActiveFileTitle.textContent !== newName) {
        elActiveFileTitle.textContent = newName;
      }
      showToast(`Đã tự động cập nhật tên file: ${newName}`);
    }
  }
}

// Helper to identify generic names that need syncing
function isGenericFileName(name) {
  if (!name) return false;
  // Remove file extension (e.g. .pdf, .docx, .mp4) before checking
  const cleanName = name.replace(/\.[a-zA-Z0-9]+$/, '').trim();
  
  // Generic Vietnamese/English academic patterns
  const genericPattern = /^(t[ệe]p\s*\d+|file\s*\d+|t[àa]i\s*li[ệe]u(?:\s*pdf)?|t[ệe]p\s*tin|b[àa]i\s*\d+|đ[ềe]\s*\d+|đ[áa]p\s*án\s*\d+|video\s*\d+|doc\s*\d+|document\s*\d+|chuy[êe]n\s*đ[ềe]\s*\d+|b[àa]i\s*gi[ảả]ng\s*\d+)$/i;
  
  return genericPattern.test(cleanName);
}

// Priority automatic sync for generic files in selected folder
async function syncFolderFilesImmediate(folder) {
  if (!folder || !folder.files) return;
  
  const genericFiles = folder.files.filter(file => isGenericFileName(file.name));
  
  if (genericFiles.length === 0) return;
  
  for (const file of genericFiles) {
    // Only fetch if still generic
    if (!isGenericFileName(file.name)) continue;
    
    const newName = await fetchFileNameFromDrive(file.driveId);
    if (newName) {
      const updated = updateFileName(file.driveId, newName);
      if (updated) {
        file.name = newName;
      }
    }
    // Small delay between requests in folder sync
    await new Promise(resolve => setTimeout(resolve, 500));
  }
}

// Background worker to sync all generic names in the database slowly
async function startBackgroundSyncAll() {
  const genericFiles = [];
  fileTreeData.forEach(category => {
    category.subjects.forEach(subject => {
      subject.folders.forEach(folder => {
        folder.files.forEach(file => {
          if (isGenericFileName(file.name)) {
            genericFiles.push({ driveId: file.driveId, file });
          }
        });
      });
    });
  });
  
  if (genericFiles.length === 0) return;
  
  console.log(`Bắt đầu đồng bộ ngầm ${genericFiles.length} file có tên chung chung...`);
  
  for (const item of genericFiles) {
    // Check if name is still generic (might have been updated by folder select or manual sync)
    if (!isGenericFileName(item.file.name)) continue;
    
    const newName = await fetchFileNameFromDrive(item.driveId);
    if (newName) {
      const updated = updateFileName(item.driveId, newName);
      if (updated) {
        item.file.name = newName;
        // If the user is currently viewing this file, update the title
        if (activeFile && activeFile.driveId === item.driveId) {
          elActiveFileTitle.textContent = newName;
        }
      }
    }
    // Wait 3 seconds to be gentle
    await new Promise(resolve => setTimeout(resolve, 3000));
  }
}

// Google Drive URL ID Parser
function extractGoogleDriveId(url) {
  if (!url) return null;
  
  // Replace HTML entity representation of & if it exists
  url = url.replace(/&amp;/g, '&');
  
  // 1. Check for standard query parameter id=...
  let match = url.match(/[?&]id=([a-zA-Z0-9_-]{25,50})/);
  if (match) return match[1];
  
  // 2. Check for path parameter /d/ID/... (matches /file/d/, /document/d/, /spreadsheets/d/, etc.)
  match = url.match(/\/d\/([a-zA-Z0-9_-]{25,50})/);
  if (match) return match[1];
  
  // 3. Check for drive/folders/ID (in case someone pastes a folder link - we can mark it or extract, but usually this is for files)
  match = url.match(/\/folders\/([a-zA-Z0-9_-]{25,50})/);
  if (match) return match[1];

  // 4. Try parsing raw ID directly if it matches Drive ID pattern (usually 33 characters)
  if (url.match(/^[a-zA-Z0-9_-]{25,45}$/)) {
    return url;
  }
  
  return null;
}

// Generate direct download URL
function getDirectDownloadUrl(driveId) {
  return `https://drive.google.com/uc?export=download&id=${driveId}`;
}

// Generate web view URL
function getWebViewUrl(driveId) {
  return `https://drive.google.com/file/d/${driveId}/view?usp=sharing`;
}

// Show Toast Alert
function showToast(message, type = 'success') {
  elToast.textContent = message;
  elToast.className = `toast show ${type}`;
  
  setTimeout(() => {
    elToast.className = 'toast';
  }, 3000);
}

function classifyCategory(folderName, files = []) {
  const text = (folderName + " " + files.map(f => f.name).join(" "))
    .toLowerCase()
    .normalize('NFC');
  
  // 1. Check ĐGNL (Đánh giá năng lực)
  const dgnlKeywords = [
    "hsa", "tsa", "dgnl", "đgnl", "đánh giá năng lực", "danh gia nang luc", 
    "đánh giá tư duy", "danh gia tu duy", "spt", "đhsp", "dhsp", "đại học sư phạm", "dai hoc su pham"
  ];
  if (dgnlKeywords.some(kw => text.includes(kw))) {
    return "Đánh giá năng lực (ĐGNL)";
  }
  
  // 2. Check Ôn thi TNTHPT
  const tnthptKeywords = [
    "tnthpt", "tốt nghiệp", "tot nghiep", "luyện đề", "luyen de", 
    "thi thử thpt", "thi thu thpt", "đề thpt", "de thpt", "thptqg", 
    "thpt quốc gia", "thpt quoc gia", "vstep", "ielts", "toeic", "b1", "b2", 
    "ve dich", "về đích", "sprint", "bứt tốc", "but toc", "cấp tốc", "cap toc",
    "thi thử tốt nghiệp", "thi thu tot nghiep"
  ];
  if (tnthptKeywords.some(kw => text.includes(kw))) {
    return "Ôn thi TNTHPT";
  }
  
  // 3. Check Lớp 12
  const l12Keywords = [
    "lớp 12", "lop 12", "đại học", "dai hoc", "thpt"
  ];
  if (l12Keywords.some(kw => text.includes(kw)) || /\b12\b/.test(text)) {
    return "Lớp 12";
  }
  
  // 4. Check Lớp 11
  const l11Keywords = ["lớp 11", "lop 11"];
  if (l11Keywords.some(kw => text.includes(kw)) || /\b11\b/.test(text)) {
    return "Lớp 11";
  }
  
  // 5. Check Lớp 10
  const l10Keywords = ["lớp 10", "lop 10"];
  if (l10Keywords.some(kw => text.includes(kw)) || /\b10\b/.test(text)) {
    return "Lớp 10";
  }
  
  // 6. Check Lớp 9
  const l9Keywords = [
    "lớp 9", "lop 9", "tuyển sinh 10", "tuyen sinh 10", 
    "vào 10", "vao 10", "lên 10", "len 10"
  ];
  if (l9Keywords.some(kw => text.includes(kw)) || /\b9\b/.test(text)) {
    return "Lớp 9";
  }
  
  return "Tài liệu chung";
}

function classifySubject(folderName, files = []) {
  const text = (folderName + " " + files.map(f => f.name).join(" "))
    .toLowerCase()
    .normalize('NFC');
  
  // Check if it's a DGNL category document first
  const dgnlKeywords = [
    "hsa", "tsa", "dgnl", "đgnl", "đánh giá năng lực", "danh gia nang luc", 
    "đánh giá tư duy", "danh gia tu duy", "spt", "đhsp", "dhsp", "đại học sư phạm", "dai hoc su pham"
  ];
  if (dgnlKeywords.some(kw => text.includes(kw))) {
    if (text.includes("hsa")) {
      return "HSA (ĐHQG Hà Nội)";
    }
    if (text.includes("tsa") || text.includes("tư duy bách khoa") || text.includes("tu duy bach khoa")) {
      return "TSA (ĐH Bách Khoa)";
    }
    if (text.includes("spt") || text.includes("sư phạm") || text.includes("su pham") || text.includes("đhsp") || text.includes("dhsp")) {
      return "SPT (ĐH Sư Phạm)";
    }
    return "ĐGNL Khác";
  }

  // Remove "lý thuyết" and "lý luận" variations to prevent false-positive physics matches
  const textWithoutTheory = text
    .replace(/lý thuyết|lí thuyết|ly thuyet|li thuyet/gi, " ")
    .replace(/lý luận|lí luận|ly luan|li luan/gi, " ");

  // Replace punctuation with spaces to enable space-boundary matching
  const cleanText = (" " + textWithoutTheory
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()\[\]]/g, " ")
    .replace(/\s+/g, " ") + " ");
  
  const subjectRules = [
    {
      name: "Toán học",
      keywords: ["toán", "toán học", "đại số", "hình học", "giải tích", "math", "tích phân", "đạo hàm", "lượng giác", "hàm số", "hinh hoc", "dai so", "casio", "vinacal", "fx580", "vst", "vsat"]
    },
    {
      name: "Ngữ văn",
      keywords: ["văn", "ngữ văn", "văn học", "tác phẩm", "thơ", "truyện", "nghị luận", "phân tích văn", "đọc hiểu", "ngu van", "van hoc", "tac pham", "tho", "thầy nhật", "thay nhat"]
    },
    {
      name: "Tiếng Anh",
      keywords: ["tiếng anh", "english", "anh", "grammar", "vocabulary", "ielts", "toeic", "listening", "reading", "tieng anh"]
    },
    {
      name: "Vật lý",
      keywords: ["vật lý", "vật lí", "lý", "lí", "physics", "dao động", "điện xoay chiều", "quang học", "sóng cơ", "hạt nhân", "vat ly", "vat li", "ly thuong", "li thuyet ly", "sóng điện từ", "vsat vật lí", "vsat vật lý"]
    },
    {
      name: "Hóa học",
      keywords: ["hóa học", "hoá học", "hóa", "hoá", "chemistry", "hữu cơ", "vô cơ", "axit", "phản ứng", "kim loại", "este", "peptit", "hoa hoc", "hoa vo co", "hoa huu co", "thí nghiệm hóa", "thi nghiem hoa", "tào việt đức", "tao viet duc"]
    },
    {
      name: "Sinh học",
      keywords: ["sinh học", "sinh", "biology", "di truyền", "tế bào", "tiến hóa", "hệ sinh thái", "adn", "arn", "nhiễm sắc thể", "sinh hoc"]
    },
    {
      name: "Lịch sử",
      keywords: ["lịch sử", "sử", "history", "kháng chiến", "chiến dịch", "triều đại", "chiến tranh", "thế giới", "cách mạng", "lich su", "lich su viet nam"]
    },
    {
      name: "Địa lý",
      keywords: ["địa lý", "địa lí", "địa", "geography", "địa tự nhiên", "địa dân cư", "địa ngành", "át lát", "atlat", "bản đồ", "sơ đồ tư duy địa", "dia ly", "dia li", "thầy tài", "thay tai"]
    }
  ];

  let bestSubject = "Khác";
  let maxMatches = 0;
  
  for (const rule of subjectRules) {
    let matches = 0;
    for (const keyword of rule.keywords) {
      const escapedKeyword = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      // Match as a whole word by checking space padding
      const regex = new RegExp(" " + escapedKeyword + " ", "gi");
      const count = (cleanText.match(regex) || []).length;
      matches += count;
    }
    if (matches > maxMatches) {
      maxMatches = matches;
      bestSubject = rule.name;
    }
  }
  
  return bestSubject;
}

// Teacher detector function
// Teacher detector function
function detectTeacher(folderName, fileName) {
  const text = (folderName + " " + fileName).toLowerCase().normalize('NFC');
  
  if (text.includes("ngọc huyền") || text.includes("cô huyền")) {
    return "Cô Ngọc Huyền LB";
  }
  if (text.includes("anh giáo kid") || text.includes("giáo kid") || text.includes("kid")) {
    return "Anh Giáo Kid";
  }
  if (text.includes("tyhh") || text.includes("tôi yêu hóa học") || text.includes("thầy thuận") || text.includes("thầy thắng") || text.includes("phạm văn thắng") || text.includes("thắng tyhh")) {
    return "Thầy Thắng (TYHH)";
  }
  if (text.includes("thầy tài") || text.includes("thay tai") || text.includes("địa lý tài") || text.includes("địa tài")) {
    return "Thầy Tài";
  }
  if (text.includes("phạm liễu") || text.includes("cô liễu")) {
    return "Cô Phạm Liễu";
  }
  if (text.includes("sương mai") || text.includes("cô mai")) {
    return "Cô Sương Mai";
  }
  if (text.includes("cô sen") || text.includes("vũ sen") || text.includes("vu sen")) {
    return "Cô Sen";
  }
  if (text.includes("thầy nhật") || text.includes("thay nhat")) {
    return "Thầy Nhật";
  }
  if (text.includes("tào việt đức") || text.includes("tao viet duc")) {
    return "Tào Việt Đức";
  }
  if (text.includes("hsa edu") || text.includes("hsa")) {
    return "HSA EDU";
  }
  if (text.includes("vnes")) {
    return "VNES";
  }
  if (text.includes("moon.vn") || text.includes("sách moon") || text.includes("moon")) {
    return "Moon.vn";
  }

  // Dynamic Thầy/Cô extraction from folder and file name
  const rawText = (folderName + " " + fileName).normalize('NFC');
  const match = rawText.match(/(thầy|cô)\s+([A-ZÀ-ỸĐa-zà-ỹđ]+(?:\s+[A-ZÀ-ỸĐa-zà-ỹđ]+){0,2})/i);
  if (match) {
    let type = match[1].charAt(0).toUpperCase() + match[1].slice(1).toLowerCase();
    let rawName = match[2].trim();
    
    // Split the name into words and remove any words that match common non-name terms or stop words
    const words = rawName.split(/\s+/);
    const stopWords = [
      "về", "đích", "ve", "dich", 
      "sơ", "đồ", "so", "do", 
      "tổng", "ôn", "tong", "on", 
      "chuyên", "đề", "chuyen", "de", 
      "luyện", "luyen", 
      "lý", "thuyết", "ly", "thuyet", 
      "bài", "tập", "giảng", "bai", "tap", "giang", 
      "tài", "liệu", "tai", "lieu", 
      "thi", "thử", "thu", 
      "đọc", "hiểu", "doc", "hieu",
      "nghị", "luận", "nghi", "luan",
      "tác", "phẩm", "tac", "pham",
      "bản", "ban",
      "đại", "học", "dai", "hoc",
      "trung", "học", "trung", "hoc",
      "phổ", "thông", "pho", "thong",
      "lớp", "lop",
      "cấp", "tốc", "cap", "toc"
    ];
    
    // We only keep the words until we hit a stop word
    const cleanedWords = [];
    for (const word of words) {
      if (stopWords.includes(word.toLowerCase())) {
        break; // Stop including words as part of the name
      }
      cleanedWords.push(word);
    }
    
    if (cleanedWords.length > 0) {
      let rawNameCleaned = cleanedWords.join(' ');
      const lowerName = rawNameCleaned.toLowerCase();
      const exclusions = ["cô", "thầy", "dạy", "giáo", "trẻ", "nhà", "khuyên", "ở", "của", "tôi", "cho", "em", "với", "đọc", "hiểu", "hướng", "dẫn", "viết", "phân", "tích", "khác", "này", "kia"];
      
      if (lowerName.length >= 2 && !exclusions.some(exc => lowerName === exc || lowerName.startsWith(exc + " ") || lowerName.endsWith(" " + exc))) {
        let formattedName = rawNameCleaned.split(/\s+/).map(word => {
          return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        }).join(' ');
        
        // Map common variations to a standardized name
        if (formattedName.toLowerCase() === "sen" || formattedName.toLowerCase() === "vũ sen") {
          formattedName = "Sen";
        }
        
        return `${type} ${formattedName}`;
      }
    }
  }

  return "Tài liệu chung";
}

// Convert category hierarchy to teacher hierarchy
function getTeacherTreeData() {
  const teacherMap = {};
  
  fileTreeData.forEach(category => {
    category.subjects.forEach(subject => {
      subject.folders.forEach(folder => {
        folder.files.forEach(file => {
          const teacherName = detectTeacher(folder.folderName, file.name);
          const subjectName = subject.subjectName;
          const folderName = folder.folderName;
          
          if (!teacherMap[teacherName]) {
            teacherMap[teacherName] = {};
          }
          if (!teacherMap[teacherName][subjectName]) {
            teacherMap[teacherName][subjectName] = {};
          }
          if (!teacherMap[teacherName][subjectName][folderName]) {
            teacherMap[teacherName][subjectName][folderName] = [];
          }
          
          if (!teacherMap[teacherName][subjectName][folderName].some(f => f.driveId === file.driveId)) {
            teacherMap[teacherName][subjectName][folderName].push(file);
          }
        });
      });
    });
  });
  
  const teacherTree = [];
  Object.keys(teacherMap).forEach(teacherName => {
    const subjectsArr = [];
    Object.keys(teacherMap[teacherName]).forEach(subjectName => {
      const foldersArr = [];
      Object.keys(teacherMap[teacherName][subjectName]).forEach(folderName => {
        foldersArr.push({
          folderName: folderName,
          files: teacherMap[teacherName][subjectName][folderName]
        });
      });
      
      foldersArr.sort((a, b) => a.folderName.localeCompare(b.folderName, 'vi', { numeric: true }));
      
      subjectsArr.push({
        subjectName: subjectName,
        folders: foldersArr
      });
    });
    
    const SUBJECT_ORDER = [
      "Toán học", "Vật lý", "Hóa học", "Sinh học", "Ngữ văn", "Lịch sử", "Địa lý", "Tiếng Anh", "HSA (ĐHQG Hà Nội)", "TSA (ĐH Bách Khoa)", "SPT (ĐH Sư Phạm)", "ĐGNL Khác", "Khác"
    ];
    subjectsArr.sort((a, b) => {
      let indexA = SUBJECT_ORDER.indexOf(a.subjectName);
      let indexB = SUBJECT_ORDER.indexOf(b.subjectName);
      if (indexA === -1) indexA = 99;
      if (indexB === -1) indexB = 99;
      if (indexA !== indexB) return indexA - indexB;
      return a.subjectName.localeCompare(b.subjectName, 'vi');
    });
    
    teacherTree.push({
      teacherName: teacherName,
      subjects: subjectsArr
    });
  });
  
  const TEACHER_ORDER = [
    "Thầy Thắng (TYHH)",
    "Cô Ngọc Huyền LB",
    "Anh Giáo Kid",
    "Thầy Tài",
    "Cô Phạm Liễu",
    "Thầy Nhật",
    "Cô Sương Mai",
    "Cô Sen",
    "Tào Việt Đức",
    "HSA EDU",
    "VNES",
    "Moon.vn",
    "Tài liệu chung"
  ];
  
  teacherTree.sort((a, b) => {
    let indexA = TEACHER_ORDER.indexOf(a.teacherName);
    let indexB = TEACHER_ORDER.indexOf(b.teacherName);
    if (indexA === -1) indexA = 98;
    if (indexB === -1) indexB = 98;
    if (a.teacherName === "Tài liệu chung") indexA = 99;
    if (b.teacherName === "Tài liệu chung") indexB = 99;
    
    if (indexA !== indexB) return indexA - indexB;
    return a.teacherName.localeCompare(b.teacherName, 'vi');
  });
  
  return teacherTree;
}

// Re-categorize the tree on reload or import
function reclassifyTree(tree) {
  if (!tree || tree.length === 0) return [];
  const newTree = [];
  
  const allFolders = [];
  tree.forEach(cat => {
    const subjects = cat.subjects || [];
    subjects.forEach(subj => {
      const folders = subj.folders || [];
      folders.forEach(folder => {
        allFolders.push(folder);
      });
    });
    
    if (cat.folders && !cat.subjects) {
      cat.folders.forEach(folder => {
        allFolders.push(folder);
      });
    }
  });
  
  allFolders.forEach(folder => {
    const categoryName = classifyCategory(folder.folderName, folder.files);
    const subjectName = classifySubject(folder.folderName, folder.files);
    
    let newCat = newTree.find(c => c.categoryName === categoryName);
    if (!newCat) {
      newCat = { categoryName, subjects: [] };
      newTree.push(newCat);
    }
    
    let newSubj = newCat.subjects.find(s => s.subjectName === subjectName);
    if (!newSubj) {
      newSubj = { subjectName, folders: [] };
      newCat.subjects.push(newSubj);
    }
    
    let existingFolder = newSubj.folders.find(f => f.folderName === folder.folderName);
    if (existingFolder) {
      folder.files.forEach(file => {
        if (!existingFolder.files.some(f => f.driveId === file.driveId)) {
          existingFolder.files.push(file);
        }
      });
    } else {
      newSubj.folders.push(folder);
    }
  });
  
  return newTree;
}

// Clean up redundant folder name prefixes and substrings from file names
function cleanFileTreeNames(tree) {
  if (!tree) return;
  tree.forEach(category => {
    if (!category.subjects) return;
    category.subjects.forEach(subject => {
      if (!subject.folders) return;
      subject.folders.forEach(folder => {
        if (!folder.files) return;
        
        const folderName = folder.folderName.trim();
        const fNameLower = folderName.toLowerCase();
        
        folder.files.forEach(file => {
          let originalName = file.name.trim();
          let nameLower = originalName.toLowerCase();
          
          // Case 1: File name contains the folder name (if folder name is >= 5 characters)
          if (fNameLower.length >= 5 && nameLower.includes(fNameLower)) {
            const index = nameLower.indexOf(fNameLower);
            let newName = originalName.substring(0, index) + originalName.substring(index + folderName.length);
            
            // Clean up leading/trailing symbols, hyphens, colons, parentheses
            newName = newName.replace(/^[-_\s()/:|[\]]+|[-_\s()/:|[\]]+$/g, '').trim();
            newName = newName.replace(/\s+/g, ' ');
            
            if (newName && newName.length >= 2) {
              file.name = newName;
            }
          } 
          // Case 2: Folder name is short but followed by a standard separator in the file name
          else if (fNameLower.length > 0) {
            const separators = [" - ", " – ", " — ", " : ", ": ", " | ", "/"];
            for (const sep of separators) {
              const prefixWithSep = fNameLower + sep.toLowerCase();
              if (nameLower.startsWith(prefixWithSep)) {
                let newName = originalName.substring(prefixWithSep.length).trim();
                newName = newName.replace(/^[-_\s()/:|[\]]+|[-_\s()/:|[\]]+$/g, '').trim();
                newName = newName.replace(/\s+/g, ' ');
                if (newName) {
                  file.name = newName;
                }
                break;
              }
            }
          }
        });
      });
    });
  });
}

// Migrate legacy 2-level localStorage format to new 3-level format
function migrateData(oldData) {
  if (!oldData || oldData.length === 0) return [];
  
  // If it's already in 4-level format (contains categoryName), return it
  if (oldData[0] && oldData[0].categoryName !== undefined) {
    return oldData;
  }
  
  const migrated = [];
  
  oldData.forEach(subjNode => {
    const folders = subjNode.folders || [subjNode];
    const rawSubjectName = subjNode.subjectName || "Khác";
    
    folders.forEach(folder => {
      const categoryName = classifyCategory(folder.folderName, folder.files);
      const subjectName = subjNode.subjectName ? rawSubjectName : classifySubject(folder.folderName, folder.files);
      
      let cat = migrated.find(c => c.categoryName === categoryName);
      if (!cat) {
        cat = { categoryName, subjects: [] };
        migrated.push(cat);
      }
      
      let subj = cat.subjects.find(s => s.subjectName === subjectName);
      if (!subj) {
        subj = { subjectName, folders: [] };
        cat.subjects.push(subj);
      }
      
      if (!subj.folders.some(f => f.folderName === folder.folderName)) {
        subj.folders.push(folder);
      }
    });
  });
  
  return migrated;
}

function sortTreeData() {
  const CATEGORY_ORDER = [
    "Đánh giá năng lực (ĐGNL)",
    "Ôn thi TNTHPT",
    "Lớp 12",
    "Lớp 11",
    "Lớp 10",
    "Lớp 9",
    "Tài liệu chung"
  ];
  
  const SUBJECT_ORDER = [
    "Toán học",
    "Vật lý",
    "Hóa học",
    "Sinh học",
    "Ngữ văn",
    "Lịch sử",
    "Địa lý",
    "Tiếng Anh",
    "HSA (ĐHQG Hà Nội)",
    "TSA (ĐH Bách Khoa)",
    "SPT (ĐH Sư Phạm)",
    "ĐGNL Khác",
    "Khác"
  ];
  
  fileTreeData.sort((a, b) => {
    let indexA = CATEGORY_ORDER.indexOf(a.categoryName);
    let indexB = CATEGORY_ORDER.indexOf(b.categoryName);
    if (indexA === -1) indexA = 99;
    if (indexB === -1) indexB = 99;
    
    if (indexA !== indexB) return indexA - indexB;
    return a.categoryName.localeCompare(b.categoryName, 'vi');
  });
  
  fileTreeData.forEach(cat => {
    cat.subjects.sort((a, b) => {
      let indexA = SUBJECT_ORDER.indexOf(a.subjectName);
      let indexB = SUBJECT_ORDER.indexOf(b.subjectName);
      if (indexA === -1) indexA = 99;
      if (indexB === -1) indexB = 99;
      
      if (indexA !== indexB) return indexA - indexB;
      return a.subjectName.localeCompare(b.subjectName, 'vi');
    });
    
    cat.subjects.forEach(subj => {
      subj.folders.sort((a, b) => a.folderName.localeCompare(b.folderName, 'vi', { numeric: true }));
      subj.folders.forEach(folder => {
        folder.files.sort((a, b) => a.name.localeCompare(b.name, 'vi', { numeric: true }));
      });
    });
  });
}

function loadData() {
  const localData = localStorage.getItem('gdrive_tree_data');
  if (localData) {
    try {
      const parsed = JSON.parse(localData);
      const migrated = migrateData(parsed);
      fileTreeData = reclassifyTree(migrated);
      
      const reclassifiedDefault = reclassifyTree(DEFAULT_TREE);
      reclassifiedDefault.forEach(defaultCat => {
        let cat = fileTreeData.find(c => c.categoryName === defaultCat.categoryName);
        if (!cat) {
          cat = { categoryName: defaultCat.categoryName, subjects: [] };
          fileTreeData.push(cat);
        }
        
        defaultCat.subjects.forEach(defaultSubj => {
          let subj = cat.subjects.find(s => s.subjectName === defaultSubj.subjectName);
          if (!subj) {
            subj = { subjectName: defaultSubj.subjectName, folders: [] };
            cat.subjects.push(subj);
          }
          
          defaultSubj.folders.forEach(defaultFolder => {
            let folder = subj.folders.find(f => f.folderName === defaultFolder.folderName);
            if (!folder) {
              folder = { folderName: defaultFolder.folderName, files: [] };
              subj.folders.push(folder);
            }
            
            defaultFolder.files.forEach(defaultFile => {
              if (!folder.files.some(f => f.driveId === defaultFile.driveId)) {
                folder.files.push(defaultFile);
              }
            });
          });
        });
      });
      
      cleanFileTreeNames(fileTreeData);
      saveData();
    } catch (e) {
      console.error("Lỗi khi tải dữ liệu từ localStorage, sử dụng mẫu mặc định", e);
      fileTreeData = reclassifyTree(DEFAULT_TREE);
      cleanFileTreeNames(fileTreeData);
      saveData();
    }
  } else {
    fileTreeData = reclassifyTree(DEFAULT_TREE);
    cleanFileTreeNames(fileTreeData);
    saveData();
  }
  updateFileCount();
}

function saveData() {
  sortTreeData();
  localStorage.setItem('gdrive_tree_data', JSON.stringify(fileTreeData));
  updateFileCount();
}

function updateFileCount() {
  let count = 0;
  fileTreeData.forEach(category => {
    category.subjects.forEach(subject => {
      subject.folders.forEach(folder => {
        count += folder.files.length;
      });
    });
  });
  elFileCount.textContent = count;
}

function renderTree(searchQuery = '') {
  elFileTree.innerHTML = '';
  const query = searchQuery.trim().toLowerCase();
  
  let totalFilesRendered = 0;
  const renderData = activeViewMode === 'teacher' ? getTeacherTreeData() : fileTreeData;
  
  const catIcons = {
    "Đánh giá năng lực (ĐGNL)": "fa-award",
    "Ôn thi TNTHPT": "fa-graduation-cap",
    "Lớp 12": "fa-school",
    "Lớp 11": "fa-book-open-reader",
    "Lớp 10": "fa-book-open",
    "Lớp 9": "fa-pencil",
    "Tài liệu chung": "fa-folder-closed"
  };

  renderData.forEach((item) => {
    const itemTitle = activeViewMode === 'teacher' ? item.teacherName : item.categoryName;
    
    if (activeViewMode === 'teacher' && query) {
      if (!itemTitle.toLowerCase().includes(query)) {
        return;
      }
    }

    const matchingSubjects = [];
    
    item.subjects.forEach(subject => {
      const matchingFolders = [];
      
      subject.folders.forEach(folder => {
        const filteredFiles = (activeViewMode === 'teacher' && query) ? folder.files : folder.files.filter(file => 
          file.name.toLowerCase().includes(query) || 
          folder.folderName.toLowerCase().includes(query) ||
          subject.subjectName.toLowerCase().includes(query) ||
          itemTitle.toLowerCase().includes(query)
        );
        
        if (filteredFiles.length > 0) {
          matchingFolders.push({
            folderName: folder.folderName,
            files: filteredFiles
          });
        }
      });
      
      if (matchingFolders.length > 0) {
        matchingSubjects.push({
          subjectName: subject.subjectName,
          folders: matchingFolders
        });
      }
    });
    
    if (matchingSubjects.length === 0) return;
    
    const categoryNode = document.createElement('div');
    categoryNode.className = query ? 'category-node open' : 'category-node';
    
    const categoryLabel = document.createElement('div');
    categoryLabel.className = 'category-label';
    
    const categoryCaret = document.createElement('i');
    categoryCaret.className = 'category-caret fa-solid fa-chevron-right';
    
    const categoryIcon = document.createElement('i');
    const catIconClass = activeViewMode === 'teacher' ? 'fa-chalkboard-user' : (catIcons[itemTitle] || "fa-folder-closed");
    categoryIcon.className = 'category-icon fa-solid ' + catIconClass;
    
    const categoryText = document.createElement('span');
    categoryText.className = 'category-title';
    categoryText.textContent = itemTitle;
    
    categoryLabel.appendChild(categoryCaret);
    categoryLabel.appendChild(categoryIcon);
    categoryLabel.appendChild(categoryText);
    categoryNode.appendChild(categoryLabel);
    
    const categoryChildren = document.createElement('div');
    categoryChildren.className = 'category-children';
    
    matchingSubjects.forEach(subject => {
      const subjectNode = document.createElement('div');
      subjectNode.className = query ? 'subject-node open' : 'subject-node';
      
      const subjectLabel = document.createElement('div');
      subjectLabel.className = 'subject-label';
      
      const subjectCaret = document.createElement('i');
      subjectCaret.className = 'subject-caret fa-solid fa-chevron-right';
      
      const subjectIcon = document.createElement('i');
      const iconClass = SUBJECT_ICONS[subject.subjectName] || "fa-folder-closed";
      subjectIcon.className = 'subject-icon fa-solid ' + iconClass;
      
      const subjectText = document.createElement('span');
      subjectText.className = 'subject-title';
      subjectText.textContent = subject.subjectName;
      
      subjectLabel.appendChild(subjectCaret);
      subjectLabel.appendChild(subjectIcon);
      subjectLabel.appendChild(subjectText);
      subjectNode.appendChild(subjectLabel);
      
      const subjectChildren = document.createElement('div');
      subjectChildren.className = 'subject-children';
      
      subject.folders.forEach(folder => {
        totalFilesRendered += folder.files.length;
        const folderNode = document.createElement('div');
        folderNode.className = 'folder-node';
        
        const folderLabel = document.createElement('div');
        folderLabel.className = 'folder-label';
        
        const folderIcon = document.createElement('i');
        folderIcon.className = 'folder-icon fa-solid fa-folder';
        
        const folderText = document.createElement('span');
        folderText.className = 'ft-label-text';
        folderText.textContent = folder.folderName;
        
        const folderDlBtn = document.createElement('i');
        folderDlBtn.className = 'folder-download-btn-sidebar fa-solid fa-cloud-arrow-down';
        folderDlBtn.title = "Tải toàn bộ thư mục";
        folderDlBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          downloadFolderFiles(folder.files);
        });
        
        folderLabel.appendChild(folderIcon);
        folderLabel.appendChild(folderText);
        folderLabel.appendChild(folderDlBtn);
        folderNode.appendChild(folderLabel);
        
        subjectChildren.appendChild(folderNode);
        
        folderLabel.addEventListener('click', (e) => {
          if (e.target !== folderDlBtn) {
            document.querySelectorAll('.folder-label').forEach(el => el.classList.remove('active'));
            folderLabel.classList.add('active');
            selectFolder(folder);
          }
        });
      });
      
      subjectNode.appendChild(subjectChildren);
      categoryChildren.appendChild(subjectNode);
      
      subjectLabel.addEventListener('click', (e) => {
        if (e.target !== subjectCaret) {
          const isOpen = subjectNode.classList.contains('open');
          if (isOpen) {
            subjectNode.classList.remove('open');
          } else {
            subjectNode.classList.add('open');
          }
        }
      });
      
      subjectCaret.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = subjectNode.classList.contains('open');
        if (isOpen) {
          subjectNode.classList.remove('open');
        } else {
          subjectNode.classList.add('open');
        }
      });
    });
    
    categoryNode.appendChild(categoryChildren);
    elFileTree.appendChild(categoryNode);
    
    categoryLabel.addEventListener('click', (e) => {
      if (e.target !== categoryCaret) {
        const isOpen = categoryNode.classList.contains('open');
        if (isOpen) {
          categoryNode.classList.remove('open');
        } else {
          categoryNode.classList.add('open');
        }
      }
    });
    
    categoryCaret.addEventListener('click', (e) => {
      e.stopPropagation();
      const isOpen = categoryNode.classList.contains('open');
      if (isOpen) {
        categoryNode.classList.remove('open');
      } else {
        categoryNode.classList.add('open');
      }
    });
  });
  
  if (totalFilesRendered === 0) {
    elFileTree.innerHTML = `<div class="tree-empty-state"><i class="fa-solid fa-magnifying-glass"></i><p>${query ? 'Không tìm thấy tệp tin phù hợp.' : 'Danh sách trống. Vui lòng thêm dữ liệu!'}</p></div>`;
  }
}

// Select file and open preview panel
function selectFile(file, folderName, pushState = true) {
  activeFile = file;
  activeFolder = null;
  
  // Toggle panels
  elEmptyPanel.classList.remove('active');
  elFolderPanel.classList.remove('active');
  elViewerPanel.classList.add('active');
  
  // Update view meta
  elActiveFileTitle.textContent = file.name;
  elActiveFileFolder.textContent = folderName;
  elActiveFileId.textContent = `ID: ${file.driveId.substring(0, 10)}...`;
  
  // Set link actions
  const directLink = getDirectDownloadUrl(file.driveId);
  elBtnDownloadDirect.href = directLink;
  elBtnOpenDrive.href = getWebViewUrl(file.driveId);
  
  // Set preview source with loading state
  elPreviewLoader.style.display = 'flex';
  elPreviewIframe.style.display = 'none';
  
  // Google Drive iframe preview link
  elPreviewIframe.src = `https://drive.google.com/file/d/${file.driveId}/preview`;

  // Highlight the folder in the sidebar tree
  document.querySelectorAll('.folder-label').forEach(el => {
    const textSpan = el.querySelector('.ft-label-text');
    if (textSpan && textSpan.textContent.trim() === folderName) {
      el.classList.add('active');
      
      // Auto expand parent subjects/categories so the highlighted folder is visible
      let parent = el.parentElement;
      while (parent && parent !== elFileTree) {
        if (parent.classList.contains('subject-node') || parent.classList.contains('category-node')) {
          parent.classList.add('open');
        }
        parent = parent.parentElement;
      }
    } else {
      el.classList.remove('active');
    }
  });

  if (pushState) {
    history.pushState({ panel: 'file', file: file, folderName: folderName }, '');
  }

  // Trigger background automatic name sync if it's a generic name
  if (isGenericFileName(file.name)) {
    autoSyncFileName(file.driveId);
  }
}

// Select folder and open folder details view
function selectFolder(folder, pushState = true) {
  activeFolder = folder;
  activeFile = null;
  
  // Remove file selection highlights
  document.querySelectorAll('.file-item').forEach(el => el.classList.remove('active'));
  
  // Toggle panels
  elEmptyPanel.classList.remove('active');
  elViewerPanel.classList.remove('active');
  elFolderPanel.classList.add('active');
  
  // Update UI Metadata
  elActiveFolderTitle.textContent = folder.folderName;
  elActiveFolderCount.textContent = folder.files.length;
  
  // Hide progress bar by default
  elBatchProgressContainer.style.display = 'none';
  elProgressBarFill.style.width = '0%';
  
  // Populate files list inside details panel
  elFolderFilesList.innerHTML = '';
  folder.files.forEach(file => {
    const card = document.createElement('div');
    card.className = 'folder-file-card';
    
    const info = document.createElement('div');
    info.className = 'folder-file-info';
    
    const icon = document.createElement('i');
    icon.className = 'fa-regular fa-file-pdf';
    
    const name = document.createElement('span');
    name.className = 'folder-file-name';
    name.textContent = file.name;
    
    info.appendChild(icon);
    info.appendChild(name);
    
    const actions = document.createElement('div');
    actions.className = 'folder-file-actions';
    
    const previewBtn = document.createElement('button');
    previewBtn.className = 'btn btn-secondary btn-sm';
    previewBtn.innerHTML = '<i class="fa-solid fa-eye"></i> Xem';
    previewBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      selectFile(file, folder.folderName);
    });
    
    const downloadBtn = document.createElement('a');
    downloadBtn.className = 'btn btn-success btn-sm';
    downloadBtn.href = getDirectDownloadUrl(file.driveId);
    downloadBtn.target = '_blank';
    downloadBtn.innerHTML = '<i class="fa-solid fa-download"></i> Tải về';
    downloadBtn.addEventListener('click', (e) => {
      e.stopPropagation();
    });
    
    actions.appendChild(previewBtn);
    actions.appendChild(downloadBtn);
    card.appendChild(info);
    card.appendChild(actions);
    
    elFolderFilesList.appendChild(card);
  });
  
  // Set up click handler for folder batch download
  elBtnDownloadFolder.onclick = () => {
    downloadFolderFiles(folder.files);
  };

  if (pushState) {
    history.pushState({ panel: 'folder', folder: folder }, '');
  }

  // Trigger priority automatic sync for generic files in this folder
  syncFolderFilesImmediate(folder);
}

// Batch download trigger with sequential setTimeout spacing
function downloadFolderFiles(files) {
  if (!files || files.length === 0) return;
  
  // Show progress container
  elBatchProgressContainer.style.display = 'block';
  elProgressText.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Đang chuẩn bị tải file 1/${files.length}...`;
  elProgressPercent.textContent = '0%';
  elProgressBarFill.style.width = '0%';
  
  showToast(`Bắt đầu tải hàng loạt ${files.length} tệp tin...`);
  
  let current = 0;
  
  files.forEach((file, index) => {
    setTimeout(() => {
      // Create download trigger element
      const a = document.createElement('a');
      a.href = getDirectDownloadUrl(file.driveId);
      a.target = '_blank';
      a.download = file.name;
      
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      
      current++;
      const percent = Math.round((current / files.length) * 100);
      
      // Update UI Progress bar
      elProgressPercent.textContent = `${percent}%`;
      elProgressBarFill.style.width = `${percent}%`;
      
      if (current < files.length) {
        elProgressText.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Đang tải file ${current + 1}/${files.length}: <strong>${files[current].name}</strong>`;
      } else {
        elProgressText.innerHTML = `<i class="fa-solid fa-circle-check" style="color: var(--color-success)"></i> Đã tải xong toàn bộ ${files.length} tệp tin!`;
        showToast(`Tải xuống thành công toàn bộ thư mục!`);
      }
    }, index * 1000); // 1-second delay spacing prevents popups block
  });
}

// --- Import Parsers ---

// Process paste input containing HTML tree
function parseAndImportHTML(htmlString) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(htmlString, 'text/html');
  
  let importedCount = 0;
  const folderElements = doc.querySelectorAll('.folder_ft');
  
  if (folderElements.length > 0) {
    folderElements.forEach(folderEl => {
      const labelTextEl = folderEl.querySelector('.ft-label-text');
      const labelEl = folderEl.querySelector('.ft-label');
      let folderName = 'Thư mục đã nhập';
      
      if (labelTextEl) {
        folderName = labelTextEl.textContent.trim();
      } else if (labelEl) {
        const clonedLabel = labelEl.cloneNode(true);
        clonedLabel.querySelectorAll('i').forEach(i => i.remove());
        folderName = clonedLabel.textContent.trim();
      }
      folderName = folderName.replace(/\s+/g, ' ');

      // Only select files that belong directly to this folder, not nested subfolders
      const allFiles = folderEl.querySelectorAll('li.file_ft, li[data-href]');
      const fileEls = Array.from(allFiles).filter(fileEl => {
        const closestFolder = fileEl.closest('.folder_ft');
        return closestFolder === folderEl;
      });
      const filesList = [];
      
      fileEls.forEach(fileEl => {
        const url = fileEl.getAttribute('data-href') || fileEl.getAttribute('href') || '';
        const driveId = extractGoogleDriveId(url);
        
        if (driveId) {
          const nameEl = fileEl.querySelector('.file_name_ft, .file-label-text, span');
          let name = '';
          if (nameEl) {
            name = nameEl.textContent.trim();
          } else {
            const clonedFile = fileEl.cloneNode(true);
            clonedFile.querySelectorAll('i, span.ft-drive-tag').forEach(el => el.remove());
            name = clonedFile.textContent.trim();
          }
          
          name = name.replace(/\s+/g, ' ');
          filesList.push({ name, url, driveId });
          importedCount++;
        }
      });
      
      if (filesList.length > 0) {
        const categoryName = classifyCategory(folderName, filesList);
        const subjectName = classifySubject(folderName, filesList);
        
        let cat = fileTreeData.find(c => c.categoryName === categoryName);
        if (!cat) {
          cat = { categoryName, subjects: [] };
          fileTreeData.push(cat);
        }
        
        let subject = cat.subjects.find(s => s.subjectName === subjectName);
        if (!subject) {
          subject = { subjectName, folders: [] };
          cat.subjects.push(subject);
        }
        
        const existingFolder = subject.folders.find(f => f.folderName === folderName);
        if (existingFolder) {
          filesList.forEach(newFile => {
            if (!existingFolder.files.some(f => f.driveId === newFile.driveId)) {
              existingFolder.files.push(newFile);
            }
          });
        } else {
          subject.folders.push({ folderName, files: filesList });
        }
      }
    });
  } else {
    const titleEl = doc.querySelector('.entry-title, h1, h2, title');
    const pageTitle = titleEl ? titleEl.textContent.trim() : '';
    
    let categoryName = '';
    const breadcrumbs = doc.querySelectorAll('#breadcrumb a, .breadcrumb a, .breadcrumbs a');
    if (breadcrumbs.length > 0) {
      for (let i = breadcrumbs.length - 1; i >= 0; i--) {
        const txt = breadcrumbs[i].textContent.trim();
        if (txt && txt.toLowerCase() !== 'home') {
          categoryName = txt;
          break;
        }
      }
    }
    
    if (!categoryName) {
      const labelLink = doc.querySelector('.label-link, a[rel="tag"]');
      if (labelLink) {
        categoryName = labelLink.textContent.trim();
      }
    }
    
    const processedIds = new Set();
    let currentHeading = '';
    const foldersMap = {}; // heading/topic name -> files array
    
    // Use TreeWalker to walk elements in document order
    const walker = doc.createTreeWalker(doc.body || doc, NodeFilter.SHOW_ELEMENT, null, false);
    let currentNode = walker.currentNode;
    while (currentNode) {
      const tagName = currentNode.tagName.toLowerCase();
      
      // Detect headings and section titles
      if (/^(h[1-6])$/.test(tagName) || currentNode.classList.contains('entry-title') || currentNode.classList.contains('folder-title')) {
        const headingText = currentNode.textContent.trim().replace(/\s+/g, ' ');
        if (headingText && headingText.length < 150) {
          currentHeading = headingText;
        }
      }
      
      const attributes = ['href', 'data-href', 'src', 'data-src', 'de', 'video', 'da'];
      attributes.forEach(attr => {
        if (currentNode.hasAttribute(attr)) {
          const val = currentNode.getAttribute(attr);
          const driveId = extractGoogleDriveId(val);
          
          if (driveId && !processedIds.has(driveId)) {
            processedIds.add(driveId);
            let name = '';
            
            // Try to extract original name from element text
            if (currentNode.tagName === 'A' && currentNode.textContent.trim() && currentNode.textContent.trim() !== val) {
              name = currentNode.textContent.trim();
            }
            
            if (tagName === 'x-file') {
              const deId = extractGoogleDriveId(currentNode.getAttribute('de'));
              const videoId = extractGoogleDriveId(currentNode.getAttribute('video'));
              const daId = extractGoogleDriveId(currentNode.getAttribute('da'));
              
              const uniqueIds = new Set([deId, videoId, daId].filter(id => id !== null));
              const baseName = currentNode.textContent.trim() || pageTitle || 'Tài liệu';
              
              if (uniqueIds.size > 1) {
                const suffix = attr === 'de' ? ' (Đề thi)' : attr === 'da' ? ' (Đáp án)' : attr === 'video' ? ' (Video)' : '';
                name = baseName + suffix;
              } else {
                name = baseName;
              }
            } else if (tagName === 'iframe') {
              name = currentNode.title || pageTitle || 'Khung xem trước PDF';
            }
            
            if (!name) {
              name = pageTitle || ('Tài liệu GDrive (' + driveId.substring(0, 6) + ')');
            }
            
            name = name.replace(/\s+/g, ' ');
            
            const folderName = currentHeading || pageTitle || categoryName || "Tệp tin nhập nhanh";
            if (!foldersMap[folderName]) {
              foldersMap[folderName] = [];
            }
            foldersMap[folderName].push({ name, url: val, driveId });
            importedCount++;
          }
        }
      });
      
      currentNode = walker.nextNode();
    }
    
    // Add all grouped files from foldersMap to tree data
    Object.keys(foldersMap).forEach(folderName => {
      const filesList = foldersMap[folderName];
      if (filesList.length > 0) {
        const fileCategory = classifyCategory(categoryName + " " + folderName, filesList);
        const subjectName = classifySubject(categoryName + " " + folderName, filesList);
        
        let cat = fileTreeData.find(c => c.categoryName === fileCategory);
        if (!cat) {
          cat = { categoryName: fileCategory, subjects: [] };
          fileTreeData.push(cat);
        }
        
        let subject = cat.subjects.find(s => s.subjectName === subjectName);
        if (!subject) {
          subject = { subjectName, folders: [] };
          cat.subjects.push(subject);
        }
        
        const existingFolder = subject.folders.find(f => f.folderName === folderName);
        if (existingFolder) {
          filesList.forEach(newFile => {
            if (!existingFolder.files.some(f => f.driveId === newFile.driveId)) {
              existingFolder.files.push(newFile);
            }
          });
        } else {
          subject.folders.push({ folderName, files: filesList });
        }
      }
    });
  }
  
  if (importedCount > 0) {
    cleanFileTreeNames(fileTreeData);
    saveData();
    renderTree();
    showToast('Đã nhập thành công ' + importedCount + ' tệp tin từ HTML!');
    closeModal();
  } else {
    showToast("Không tìm thấy tệp tin Google Drive nào hợp lệ trong HTML dán vào.", "error");
  }
}

// Single file import
function importSingleFile(url, name, folderName) {
  const driveId = extractGoogleDriveId(url);
  if (!driveId) {
    showToast("Đường dẫn Google Drive không hợp lệ! Vui lòng kiểm tra lại.", "error");
    return;
  }
  
  const finalFolderName = folderName.trim() || "Thư mục chung";
  const finalFileName = name.trim() || ('Tài liệu PDF (' + driveId.substring(0, 6) + ')');
  
  const newFile = {
    name: finalFileName,
    url: url,
    driveId: driveId
  };
  
  const categoryName = classifyCategory(finalFolderName, [newFile]);
  const subjectName = classifySubject(finalFolderName, [newFile]);
  
  let cat = fileTreeData.find(c => c.categoryName === categoryName);
  if (!cat) {
    cat = { categoryName, subjects: [] };
    fileTreeData.push(cat);
  }
  
  let subject = cat.subjects.find(s => s.subjectName === subjectName);
  if (!subject) {
    subject = { subjectName, folders: [] };
    cat.subjects.push(subject);
  }
  
  const existingFolder = subject.folders.find(f => f.folderName === finalFolderName);
  if (existingFolder) {
    if (existingFolder.files.some(f => f.driveId === driveId)) {
      showToast("Tệp tin này đã tồn tại trong danh sách!", "error");
      return;
    }
    existingFolder.files.push(newFile);
  } else {
    subject.folders.push({
      folderName: finalFolderName,
      files: [newFile]
    });
  }
  
  saveData();
  renderTree();
  showToast("Đã thêm tệp tin mới thành công!");
  closeModal();
  
  selectFile(newFile, finalFolderName);
}

// Render search suggestions dropdown
function renderSearchSuggestions(query) {
  elSearchSuggestions.innerHTML = '';
  const trimmed = query.trim().toLowerCase();
  
  if (!trimmed) {
    let populars = [];
    if (activeViewMode === 'teacher') {
      populars = [
        { text: "Cô Ngọc Huyền LB", icon: "fa-chalkboard-user" },
        { text: "Thầy Tài", icon: "fa-chalkboard-user" },
        { text: "Anh Giáo Kid", icon: "fa-chalkboard-user" },
        { text: "Thầy Thắng (TYHH)", icon: "fa-chalkboard-user" }
      ];
    } else {
      populars = [
        { text: "Đề thi thử", icon: "fa-file-signature" },
        { text: "Đánh giá năng lực", icon: "fa-award" },
        { text: "Casio", icon: "fa-calculator" }
      ];
    }
    
    const header = document.createElement('div');
    header.className = 'suggestion-header';
    header.textContent = 'Gợi ý phổ biến';
    elSearchSuggestions.appendChild(header);
    
    populars.forEach(pop => {
      const item = document.createElement('div');
      item.className = 'suggestion-item';
      item.innerHTML = `<i class="fa-solid ${pop.icon} tag"></i> <span>${pop.text}</span>`;
      item.addEventListener('mousedown', (e) => {
        e.preventDefault();
        elSearchInput.value = pop.text;
        currentSearchQuery = pop.text;
        renderTree(pop.text);
        elSearchSuggestions.classList.remove('active');
      });
      elSearchSuggestions.appendChild(item);
    });
    
    elSearchSuggestions.classList.add('active');
    return;
  }
  
  const matches = {
    teachers: new Set(),
    folders: new Set()
  };
  
  fileTreeData.forEach(cat => {
    cat.subjects.forEach(subj => {
      subj.folders.forEach(folder => {
        const folderName = folder.folderName;
        
        if (activeViewMode === 'teacher') {
          const teacher = detectTeacher(folderName, "");
          if (teacher !== "Tài liệu chung" && teacher.toLowerCase().includes(trimmed)) {
            matches.teachers.add(teacher);
          }
        } else {
          if (folderName.toLowerCase().includes(trimmed)) {
            matches.folders.add(folderName);
          }
        }
      });
    });
  });
  
  let suggestionCount = 0;
  
  if (activeViewMode === 'teacher') {
    if (matches.teachers.size > 0) {
      const header = document.createElement('div');
      header.className = 'suggestion-header';
      header.textContent = 'Giáo viên';
      elSearchSuggestions.appendChild(header);
      
      Array.from(matches.teachers).slice(0, 10).forEach(teacher => {
        suggestionCount++;
        const item = document.createElement('div');
        item.className = 'suggestion-item';
        item.innerHTML = `<i class="fa-solid fa-chalkboard-user tag"></i> <span>${teacher}</span>`;
        item.addEventListener('mousedown', (e) => {
          e.preventDefault();
          elSearchInput.value = teacher;
          currentSearchQuery = teacher;
          renderTree(teacher);
          elSearchSuggestions.classList.remove('active');
        });
        elSearchSuggestions.appendChild(item);
      });
    }
  } else {
    if (matches.folders.size > 0) {
      const header = document.createElement('div');
      header.className = 'suggestion-header';
      header.textContent = 'Thư mục';
      elSearchSuggestions.appendChild(header);
      
      Array.from(matches.folders).slice(0, 5).forEach(folderName => {
        suggestionCount++;
        const item = document.createElement('div');
        item.className = 'suggestion-item';
        item.innerHTML = `<i class="fa-solid fa-folder folder"></i> <span>${folderName}</span>`;
        item.addEventListener('mousedown', (e) => {
          e.preventDefault();
          elSearchInput.value = folderName;
          currentSearchQuery = folderName;
          renderTree(folderName);
          elSearchSuggestions.classList.remove('active');
        });
        elSearchSuggestions.appendChild(item);
      });
    }
  }
  
  if (suggestionCount > 0) {
    elSearchSuggestions.classList.add('active');
  } else {
    elSearchSuggestions.classList.remove('active');
  }
}

// --- UI Actions & Events ---

// Open Import Modal
function openModal(defaultTab = 'tab-html') {
  elImportModal.classList.add('active');
  
  tabButtons.forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === defaultTab);
  });
  tabContents.forEach(content => {
    content.classList.toggle('active', content.id === defaultTab);
  });
  
  if (defaultTab === 'tab-html') {
    elHtmlImportInput.focus();
  } else {
    elSingleLinkUrl.focus();
  }
}

// Close Modal
function closeModal() {
  elImportModal.classList.remove('active');
  elHtmlImportInput.value = '';
  elSingleLinkUrl.value = '';
  elSingleLinkName.value = '';
  elSingleLinkFolder.value = '';
}

// --- Theme & Mode Management ---

function initAppTheme() {
  const savedTheme = localStorage.getItem('theme') || 'dark';
  activeTheme = savedTheme;
  
  if (savedTheme === 'light') {
    document.documentElement.classList.add('light-theme');
    document.body.classList.add('light-theme');
    if (elThemeToggleFloating) elThemeToggleFloating.innerHTML = '<i class="fa-solid fa-sun"></i>';
    if (elThemeToggleDocs) elThemeToggleDocs.innerHTML = '<i class="fa-solid fa-sun"></i>';
    if (elThemeToggleRoadmap) elThemeToggleRoadmap.innerHTML = '<i class="fa-solid fa-sun"></i>';
  } else {
    document.documentElement.classList.remove('light-theme');
    document.body.classList.remove('light-theme');
    if (elThemeToggleFloating) elThemeToggleFloating.innerHTML = '<i class="fa-solid fa-moon"></i>';
    if (elThemeToggleDocs) elThemeToggleDocs.innerHTML = '<i class="fa-solid fa-moon"></i>';
    if (elThemeToggleRoadmap) elThemeToggleRoadmap.innerHTML = '<i class="fa-solid fa-moon"></i>';
  }
}

function toggleAppTheme() {
  const newTheme = activeTheme === 'dark' ? 'light' : 'dark';
  localStorage.setItem('theme', newTheme);
  initAppTheme();
  showToast(`Đã chuyển sang giao diện ${newTheme === 'light' ? 'Sáng' : 'Tối'}!`);
}

function switchAppMode(mode) {
  activeMode = mode;
  localStorage.setItem('activeMode', mode);
  
  if (mode === 'selector') {
    elWelcomeSelector.classList.add('active');
    elDocumentsApp.classList.remove('active');
    elRoadmapApp.classList.remove('active');
    elPreviewIframe.src = '';
  } else if (mode === 'documents') {
    elWelcomeSelector.classList.remove('active');
    elDocumentsApp.classList.add('active');
    elRoadmapApp.classList.remove('active');
    renderTree(currentSearchQuery);
  } else if (mode === 'roadmap') {
    elWelcomeSelector.classList.remove('active');
    elDocumentsApp.classList.remove('active');
    elRoadmapApp.classList.add('active');
    renderRoadmapSubjectsSidebar();
    selectRoadmapTab(currentRoadmapTab);
    updateRoadmapProgress();
  }
}

// --- Roadmap Dashboard Logic ---

function renderRoadmapSubjectsSidebar() {
  if (!elRoadmapSubjectsList) return;
  elRoadmapSubjectsList.innerHTML = '';
  
  Object.keys(ROADMAP_SUBJECTS).forEach(subjName => {
    const item = document.createElement('div');
    item.className = 'folder-label';
    item.setAttribute('data-roadmap-tab', subjName);
    if (currentRoadmapTab === subjName) {
      item.classList.add('active');
    }
    
    const icon = document.createElement('i');
    icon.className = `folder-icon fa-solid ${SUBJECT_ICONS[subjName] || 'fa-book'}`;
    icon.style.color = 'var(--color-primary)';
    
    const text = document.createElement('span');
    text.className = 'ft-label-text';
    text.textContent = subjName;
    
    item.appendChild(icon);
    item.appendChild(text);
    elRoadmapSubjectsList.appendChild(item);
    
    item.addEventListener('click', () => {
      selectRoadmapTab(subjName);
    });
  });
}

function selectRoadmapTab(tabName) {
  currentRoadmapTab = tabName;
  
  // Highlight in sidebar
  document.querySelectorAll('#roadmap-app .folder-label').forEach(el => {
    if (el.getAttribute('data-roadmap-tab') === tabName) {
      el.classList.add('active');
    } else {
      el.classList.remove('active');
    }
  });
  
  if (tabName === 'phases') {
    if (elRoadmapMainTitle) elRoadmapMainTitle.textContent = 'Các Giai Đoạn Ôn Thi';
    if (elRoadmapTabPhases) elRoadmapTabPhases.classList.add('active');
    if (elRoadmapTabSubject) elRoadmapTabSubject.classList.remove('active');
    if (elRoadmapTabTodos) elRoadmapTabTodos.classList.remove('active');
    renderPhases();
  } else if (tabName === 'todos') {
    if (elRoadmapMainTitle) elRoadmapMainTitle.textContent = 'Kế Hoạch Cá Nhân (Todo)';
    if (elRoadmapTabPhases) elRoadmapTabPhases.classList.remove('active');
    if (elRoadmapTabSubject) elRoadmapTabSubject.classList.remove('active');
    if (elRoadmapTabTodos) elRoadmapTabTodos.classList.add('active');
    renderTodos();
  } else {
    if (elRoadmapMainTitle) elRoadmapMainTitle.textContent = `Lộ trình ôn tập môn ${tabName}`;
    if (elRoadmapTabPhases) elRoadmapTabPhases.classList.remove('active');
    if (elRoadmapTabSubject) elRoadmapTabSubject.classList.add('active');
    if (elRoadmapTabTodos) elRoadmapTabTodos.classList.remove('active');
    renderSubjectRoadmap(tabName);
  }
}

function renderPhases() {
  if (!elRoadmapTabPhases) return;
  elRoadmapTabPhases.innerHTML = '';
  
  const container = document.createElement('div');
  container.className = 'roadmap-phases-container';
  
  ROADMAP_PHASES.forEach((phase, pIndex) => {
    const card = document.createElement('div');
    card.className = 'phase-card';
    
    const numDiv = document.createElement('div');
    numDiv.className = 'phase-num';
    numDiv.textContent = phase.phaseNum;
    
    const contentDiv = document.createElement('div');
    contentDiv.className = 'phase-content';
    
    const titleH3 = document.createElement('h3');
    titleH3.innerHTML = `${phase.title} <span style="font-size: 12.5px; font-weight: normal; color: var(--color-primary); margin-left: 8px;">(${phase.time})</span>`;
    
    const descP = document.createElement('p');
    descP.textContent = phase.desc;
    
    const milestonesDiv = document.createElement('div');
    milestonesDiv.className = 'phase-milestones';
    
    phase.milestones.forEach((ms, mIndex) => {
      const msKey = `phase_${pIndex}_ms_${mIndex}`;
      const isChecked = !!roadmapProgress[msKey];
      
      const label = document.createElement('label');
      label.className = isChecked ? 'milestone-item checked' : 'milestone-item';
      
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = isChecked;
      
      const span = document.createElement('span');
      span.textContent = ms;
      
      label.appendChild(checkbox);
      label.appendChild(span);
      milestonesDiv.appendChild(label);
      
      checkbox.addEventListener('change', () => {
        roadmapProgress[msKey] = checkbox.checked;
        saveRoadmapProgress();
        label.classList.toggle('checked', checkbox.checked);
        updateRoadmapProgress();
      });
    });
    
    contentDiv.appendChild(titleH3);
    contentDiv.appendChild(descP);
    contentDiv.appendChild(milestonesDiv);
    
    card.appendChild(numDiv);
    card.appendChild(contentDiv);
    container.appendChild(card);
  });
  
  elRoadmapTabPhases.appendChild(container);
}

function renderSubjectRoadmap(subjectName) {
  if (!elSubjectChaptersList) return;
  elSubjectChaptersList.innerHTML = '';
  
  const chapters = ROADMAP_SUBJECTS[subjectName] || [];
  let checkedCount = 0;
  let totalCount = 0;
  
  chapters.forEach((chapter, cIndex) => {
    const card = document.createElement('div');
    card.className = 'chapter-card';
    
    const header = document.createElement('div');
    header.className = 'chapter-header';
    
    const title = document.createElement('div');
    title.className = 'chapter-title';
    title.textContent = chapter.chapterName;
    
    header.appendChild(title);
    card.appendChild(header);
    
    const milestonesDiv = document.createElement('div');
    milestonesDiv.className = 'chapter-milestones';
    
    chapter.milestones.forEach((ms, mIndex) => {
      totalCount++;
      const msKey = `subj_${subjectName}_chap_${cIndex}_ms_${mIndex}`;
      const isChecked = !!roadmapProgress[msKey];
      if (isChecked) checkedCount++;
      
      const label = document.createElement('label');
      label.className = isChecked ? 'milestone-item checked' : 'milestone-item';
      
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = isChecked;
      
      const span = document.createElement('span');
      span.textContent = ms;
      
      label.appendChild(checkbox);
      label.appendChild(span);
      milestonesDiv.appendChild(label);
      
      checkbox.addEventListener('change', () => {
        roadmapProgress[msKey] = checkbox.checked;
        saveRoadmapProgress();
        label.classList.toggle('checked', checkbox.checked);
        
        // Recalculate local progress bar
        let newChecked = 0;
        let newTotal = 0;
        chapters.forEach((ch, chIdx) => {
          ch.milestones.forEach((_, msIdx) => {
            newTotal++;
            if (roadmapProgress[`subj_${subjectName}_chap_${chIdx}_ms_${msIdx}`]) {
              newChecked++;
            }
          });
        });
        const percent = newTotal > 0 ? Math.round((newChecked / newTotal) * 100) : 0;
        if (elSubjectProgressPercent) elSubjectProgressPercent.textContent = `${percent}%`;
        if (elSubjectProgressBarFill) elSubjectProgressBarFill.style.width = `${percent}%`;
        
        updateRoadmapProgress();
      });
    });
    
    card.appendChild(milestonesDiv);
    elSubjectChaptersList.appendChild(card);
  });
  
  const percent = totalCount > 0 ? Math.round((checkedCount / totalCount) * 100) : 0;
  if (elSubjectProgressPercent) elSubjectProgressPercent.textContent = `${percent}%`;
  if (elSubjectProgressBarFill) elSubjectProgressBarFill.style.width = `${percent}%`;
}

function updateRoadmapProgress() {
  let checked = 0;
  let total = 0;
  
  ROADMAP_PHASES.forEach((phase, pIndex) => {
    phase.milestones.forEach((_, mIndex) => {
      total++;
      if (roadmapProgress[`phase_${pIndex}_ms_${mIndex}`]) {
        checked++;
      }
    });
  });
  
  Object.keys(ROADMAP_SUBJECTS).forEach(subjName => {
    ROADMAP_SUBJECTS[subjName].forEach((chapter, cIndex) => {
      chapter.milestones.forEach((_, mIndex) => {
        total++;
        if (roadmapProgress[`subj_${subjName}_chap_${cIndex}_ms_${mIndex}`]) {
          checked++;
        }
      });
    });
  });
  
  const globalPercent = total > 0 ? Math.round((checked / total) * 100) : 0;
  if (elGlobalRoadmapProgress) elGlobalRoadmapProgress.textContent = `${globalPercent}%`;
}

function renderTodos() {
  if (!elTodoList) return;
  elTodoList.innerHTML = '';
  
  if (roadmapTodos.length === 0) {
    elTodoList.innerHTML = `
      <div style="text-align: center; padding: 40px 20px; color: var(--text-muted);">
        <i class="fa-solid fa-list-check" style="font-size: 36px; margin-bottom: 16px; opacity: 0.4; color: var(--color-success)"></i>
        <p style="font-size: 14px;">Danh sách việc cần làm trống.</p>
        <p style="font-size: 12px; margin-top: 4px; opacity: 0.8;">Hãy thêm mục tiêu học tập mới bằng ô nhập phía trên.</p>
      </div>
    `;
    return;
  }
  
  roadmapTodos.forEach(todo => {
    const card = document.createElement('div');
    card.className = todo.completed ? 'todo-card completed' : 'todo-card';
    
    const textGroup = document.createElement('div');
    textGroup.className = 'todo-text-group';
    
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;
    
    const textSpan = document.createElement('span');
    textSpan.className = 'todo-text';
    textSpan.textContent = todo.text;
    
    textGroup.appendChild(checkbox);
    textGroup.appendChild(textSpan);
    
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'btn-delete-todo';
    deleteBtn.innerHTML = '<i class="fa-regular fa-trash-can"></i>';
    deleteBtn.title = 'Xóa nhiệm vụ';
    
    card.appendChild(textGroup);
    card.appendChild(deleteBtn);
    elTodoList.appendChild(card);
    
    checkbox.addEventListener('change', () => {
      todo.completed = checkbox.checked;
      saveRoadmapTodos();
      card.classList.toggle('completed', checkbox.checked);
    });
    
    deleteBtn.addEventListener('click', () => {
      roadmapTodos = roadmapTodos.filter(t => t.id !== todo.id);
      saveRoadmapTodos();
      renderTodos();
    });
  });
}

function saveRoadmapProgress() {
  localStorage.setItem('roadmap_progress', JSON.stringify(roadmapProgress));
}

// Save Todo items to LocalStorage
function saveRoadmapTodos() {
  localStorage.setItem('roadmap_todos', JSON.stringify(roadmapTodos));
}

// --- UI Actions & Events ---

// Init Event Listeners
function initEventListeners() {
  const resetToWelcome = () => {
    document.querySelectorAll('.file-item').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.folder-label').forEach(el => el.classList.remove('active'));
    elViewerPanel.classList.remove('active');
    elFolderPanel.classList.remove('active');
    elEmptyPanel.classList.add('active');
    elPreviewIframe.src = '';
    activeFile = null;
    activeFolder = null;
    elSearchInput.value = '';
    currentSearchQuery = '';
    elSearchSuggestions.classList.remove('active');
    renderTree('');
  };

  const closeActivePanel = () => {
    elViewerPanel.classList.remove('active');
    elFolderPanel.classList.remove('active');
    elEmptyPanel.classList.add('active');
    elPreviewIframe.src = '';
    activeFile = null;
    activeFolder = null;
  };

  const logo = document.querySelector('.logo');
  if (logo) {
    logo.addEventListener('click', resetToWelcome);
  }

  const btnCloseViewer = document.getElementById('btn-close-viewer');
  if (btnCloseViewer) {
    btnCloseViewer.addEventListener('click', () => history.back());
  }

  const btnCloseFolder = document.getElementById('btn-close-folder');
  if (btnCloseFolder) {
    btnCloseFolder.addEventListener('click', () => history.back());
  }

  // Intercept native mobile swipe-back / browser back gestures
  window.addEventListener('popstate', (e) => {
    const state = e.state;
    if (state && state.panel === 'file') {
      selectFile(state.file, state.folderName, false);
    } else if (state && state.panel === 'folder') {
      selectFolder(state.folder, false);
    } else {
      closeActivePanel();
    }
  });

  // Ensure initial history state is clean on fresh load
  history.replaceState(null, '');

  // Suggestions and Search Input handling
  elSearchInput.addEventListener('focus', (e) => {
    renderSearchSuggestions(e.target.value);
  });

  elSearchInput.addEventListener('input', (e) => {
    if (e.target.value === '') {
      currentSearchQuery = '';
      renderTree('');
    }
    renderSearchSuggestions(e.target.value);
  });

  elSearchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      currentSearchQuery = e.target.value;
      renderTree(currentSearchQuery);
      elSearchSuggestions.classList.remove('active');
    }
  });
  
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.search-box')) {
      elSearchSuggestions.classList.remove('active');
    }
  });

  // View Mode Switcher tabs
  viewModeButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      viewModeButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeViewMode = btn.dataset.mode;
      renderTree(currentSearchQuery);
    });
  });
  
  elBtnOpenImport.addEventListener('click', () => openModal('tab-html'));
  if (elBtnWelcomeImport) elBtnWelcomeImport.addEventListener('click', () => openModal('tab-html'));
  if (elBtnEmptyImport) elBtnEmptyImport.addEventListener('click', () => openModal('tab-html'));
  
  elBtnCloseModal.addEventListener('click', closeModal);
  elBtnCancelImport.addEventListener('click', closeModal);
  
  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetTab = btn.dataset.tab;
      
      tabButtons.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));
      
      btn.classList.add('active');
      document.getElementById(targetTab).classList.add('active');
    });
  });
  
  elImportModal.addEventListener('click', (e) => {
    if (e.target === elImportModal) closeModal();
  });
  
  elBtnProcessImport.addEventListener('click', () => {
    const activeTab = document.querySelector('.tab-btn.active').dataset.tab;
    
    if (activeTab === 'tab-html') {
      const htmlText = elHtmlImportInput.value;
      if (!htmlText.trim()) {
        showToast("Vui lòng dán đoạn mã HTML chứa danh sách tài liệu!", "error");
        return;
      }
      parseAndImportHTML(htmlText);
    } else {
      const url = elSingleLinkUrl.value;
      const name = elSingleLinkName.value;
      const folder = elSingleLinkFolder.value;
      
      if (!url.trim()) {
        showToast("Vui lòng điền link Google Drive!", "error");
        return;
      }
      importSingleFile(url, name, folder);
    }
  });
  
  elBtnCopyLink.addEventListener('click', () => {
    if (!activeFile) return;
    const directUrl = getDirectDownloadUrl(activeFile.driveId);
    
    navigator.clipboard.writeText(directUrl).then(() => {
      showToast("Đã sao chép link tải trực tiếp vào clipboard!");
    }).catch(err => {
      console.error("Không thể sao chép link", err);
      showToast("Lỗi khi sao chép link!", "error");
    });
  });

  const btnSyncName = document.getElementById('btn-sync-name');
  if (btnSyncName) {
    btnSyncName.addEventListener('click', syncActiveFileName);
  }
  
  elBtnClearAll.addEventListener('click', () => {
    if (confirm("Bạn có chắc chắn muốn xóa toàn bộ danh sách file? Hành động này không thể hoàn tác.")) {
      fileTreeData = [];
      saveData();
      renderTree();
      
      elViewerPanel.classList.remove('active');
      elFolderPanel.classList.remove('active');
      elEmptyPanel.classList.add('active');
      elPreviewIframe.src = '';
      activeFile = null;
      activeFolder = null;
      
      showToast("Đã xóa sạch dữ liệu.");
    }
  });

  elPreviewIframe.addEventListener('load', () => {
    elPreviewLoader.style.display = 'none';
    elPreviewIframe.style.display = 'block';
  });

  // --- Welcome Selector Events ---
  if (elCardGotoDocs) {
    elCardGotoDocs.addEventListener('click', () => switchAppMode('documents'));
  }
  if (elCardGotoRoadmap) {
    elCardGotoRoadmap.addEventListener('click', () => switchAppMode('roadmap'));
  }
  if (elBtnBackToSelectorDocs) {
    elBtnBackToSelectorDocs.addEventListener('click', () => switchAppMode('selector'));
  }
  if (elBtnBackToSelectorRoadmap) {
    elBtnBackToSelectorRoadmap.addEventListener('click', () => switchAppMode('selector'));
  }

  // --- Global Theme Swapping ---
  if (elThemeToggleFloating) {
    elThemeToggleFloating.addEventListener('click', toggleAppTheme);
  }
  if (elThemeToggleDocs) {
    elThemeToggleDocs.addEventListener('click', toggleAppTheme);
  }
  if (elThemeToggleRoadmap) {
    elThemeToggleRoadmap.addEventListener('click', toggleAppTheme);
  }

  // --- Roadmap tab navigation ---
  document.querySelectorAll('#roadmap-app .folder-label[data-roadmap-tab]').forEach(el => {
    el.addEventListener('click', () => {
      const tab = el.getAttribute('data-roadmap-tab');
      selectRoadmapTab(tab);
    });
  });

  // --- Todo Submit listener ---
  if (elTodoForm) {
    elTodoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const text = elTodoInput.value.trim();
      if (text) {
        roadmapTodos.push({
          id: Date.now(),
          text: text,
          completed: false
        });
        saveRoadmapTodos();
        elTodoInput.value = '';
        renderTodos();
        showToast('Đã thêm mục tiêu học tập mới!');
      }
    });
  }
}

// --- App Entry point ---
document.addEventListener('DOMContentLoaded', () => {
  // Load documents tree data
  loadData();
  renderTree();
  
  // Load theme
  initAppTheme();
  
  // Load roadmap progress & todos
  try {
    const savedProgress = localStorage.getItem('roadmap_progress');
    roadmapProgress = savedProgress ? JSON.parse(savedProgress) : {};
    
    const savedTodos = localStorage.getItem('roadmap_todos');
    roadmapTodos = savedTodos ? JSON.parse(savedTodos) : [];
  } catch (e) {
    console.error("Lỗi khi tải dữ liệu lộ trình học tập", e);
    roadmapProgress = {};
    roadmapTodos = [];
  }
  
  // Bind all event listeners
  initEventListeners();
  
  // Load saved mode or default to selector
  const savedMode = localStorage.getItem('activeMode') || 'selector';
  switchAppMode(savedMode);

  // Start background sync for all generic files
  startBackgroundSyncAll();
});
